          const y1 = b.y - (b.y > ch2e ? h2 : -h2)
          const d = 'M ' + ax + ' ' + y0 + ' L ' + ax + ' ' + ch1e
            + ' L ' + bx + ' ' + ch1e + ' L ' + bx + ' ' + y1
          return { d, lblX: (ax + bx) / 2, lblY: ch1e, labelAxis: 'x' }
