            const planned = modelStructure ? connectionStructurePatch(baseline, modelId, modelStructure) : connectionRolePatch(baseline, modelId, changes)
            const request = graphCommitRequest(planned.graph, baseline, revision)
            const signature = JSON.stringify(request)
            if (currentResultRef.current !== openingView || graphRevisionRef.current !== revision) throw new Error('页面已变化，未保存方向')
            if (!preview) {
              const checked = await host.call('graph-commit-preview', request)
              if (checked?.error || checked?.valid !== true || checked.documentId !== documentId || checked.revision !== revision) {
                const issue = modelStructure && checked?.error?.issues?.find(issue => issue.code === 'model_structure_invalid')
                throw new Error(issue?.detail || checked?.error?.message || '修改预览未通过校验')
              }
              return { signature, diff: planned.diff, ...(modelStructure ? { changes: planned.changes } : {}) }
            }
            if (preview.signature !== signature) throw new Error('预览后修改内容已变化，请重新预览')
            const saved = await host.call('graph-commit', request)
            if (saved?.error || saved?.documentId !== documentId || saved?.revision !== revision + 1 || !saved.graph) throw new Error(saved?.error?.message || '保存结果未确认，请重新载入核对')
            if (modelStructure && JSON.stringify(saved.graph.nodes.find(node => node.id === modelId)?.modelStructure) !== JSON.stringify(modelStructure)) throw new Error('保存结果未包含预览中的模型结构，草稿保留，请重新载入核对。')
            if (currentResultRef.current === openingView) {
              graphRevisionRef.current = saved.revision
              setResultView(makeView(saved.graph, fullText || openingView.sourceText || ''))
              setVerification(saved.graph.verification?.lastReport || null)
              setQuestionResult(null)
            }
